<?php
require_once ROOT.'/src/community-audit.php';
require_once ROOT.'/views/social-cards.php';
function networkCreationChoices(bool $standalone=false): void {
 $selected=$standalone?($_POST['post_kind']??$_GET['kind']??$GLOBALS['sc_composer_kind']??(socialUser()?'experience':'')):'';
 $choices=[];foreach(publicationTypes() as $kind=>$definition)$choices[]=[$kind,scIcon($definition['icon']),$definition['label'],'/community/create/?kind='.$kind];
 echo '<div class="network-create-types'.($standalone?' network-create-screen':'').'">';
 foreach($choices as [$kind,$icon,$label,$url])echo '<a href="'.e(languageUrl($url,siteLanguage())).'"'.($kind===$selected?' aria-current="page"':'').'><span aria-hidden="true">'.$icon.'</span> <span class="network-create-label">'.e(publicationLabel($kind)).'</span></a>';
 echo '</div>';
}
function networkButton(string $edge,string $kind,string $id,string $label,?bool $on=null): void {
 $displayLabel=e($label);if(preg_match('/^[♡♧]\s*/u',$label)){$displayLabel=($edge==='save'?scIcon('save'):'<span class="network-action-icon" aria-hidden="true">♡</span>').'<span class="network-action-label">'.e(preg_replace('/^[♡♧]\s*/u','',$label)).'</span>';}
 $u=socialUser();if(!$u&&$edge==='save'&&in_array($kind,['catalog','place'],true)){echo '<button type="button" class="network-action" data-guest-save="'.e($kind==='place'?'community-'.$id:$id).'" aria-pressed="false">'.scIcon('save').'<span class="sr-only">'.e($label).'</span></button>';return;}if(!$u){echo '<a class="network-action" href="'.e(networkLoginUrl()).'">'.($kind==='catalog'?'<span class="sr-only">'.e($label).'</span>'.scIcon('save'):$displayLabel).'</a>';return;}
 $key=in_array($edge,['follow','block'],true)?$id:$kind.':'.$id;$storedEdge=$edge==='follow'&&$kind==='city'?'follow_city':$edge;$exists=(bool)socialQuery('SELECT 1 FROM network_edges WHERE actor=? AND kind=? AND target=?',[$u['id'],$storedEdge,$key])->fetchColumn();$on=$on??!$exists;if($edge==='follow'&&$exists)$label=nt('following');
 echo '<form method="post" class="network-inline">'.csrf().networkContentLanguageField().'<input type="hidden" name="network_action" value="edge"><input type="hidden" name="edge" value="'.e($edge).'"><input type="hidden" name="kind" value="'.e($kind).'"><input type="hidden" name="target" value="'.e($id).'"><input type="hidden" name="on" value="'.($on?'1':'0').'"><button class="network-action'.($exists?' is-on':'').'" aria-pressed="'.($exists?'true':'false').'">'.($kind==='catalog'?'<span class="sr-only">'.e($label).'</span>'.scIcon('save'):($edge==='follow'?e($label):$displayLabel)).'</button></form>';
}
function networkAuthor(string $id,int $updated=0): void {$p=networkProfile($id);if(!$p)return;echo '<div class="network-author"><a class="network-author-link" href="'.e(languageUrl('/community/members/'.$p['handle'].'/',siteLanguage())).'">'.networkAvatar($p).'<span><strong>'.e($p['name']?:$p['handle']).'</strong><small>'.e($p['business']?nt('business'):('@'.$p['handle'])).($updated?' · '.gmdate('d.m.Y',$updated):'').'</small></span></a>';if((socialUser()['id']??'')!==$id)networkButton('follow','member',$id,nt('follow'));echo '</div>';}
function networkComments(string $kind,string $id): void {
 $u=socialUser();scSchema();sxSchema();sxContinuations($kind,$id);echo '<section class="network-comments" id="comments"><h2>'.e(nt('comments')).'</h2>';
 $rows=socialQuery("SELECT c.*,m.handle FROM network_comments c JOIN members m ON m.id=c.owner WHERE c.kind=? AND c.target=? AND c.state='published' AND m.state='active' AND NOT EXISTS(SELECT 1 FROM network_edges e WHERE e.kind='block' AND ((e.actor=? AND e.target=c.owner) OR(e.actor=c.owner AND e.target=?))) ORDER BY created LIMIT 100",[$kind,$id,$u['id']??'',$u['id']??''])->fetchAll();
 if(!$rows)echo '<p>'.e(nt('no_comments')).'</p>';
 foreach($rows as $c){if(crHidden('comment',$c['id']))continue;echo '<article class="network-comment" id="comment-'.e($c['id']).'" data-sx-source="'.e(json_encode(['kind'=>$kind,'target'=>$id,'comment'=>$c['id'],'edition'=>$c['language']])).'">';networkAuthor($c['owner'],(int)$c['created']);$parent=socialQuery('SELECT parent FROM social_comment_parents WHERE comment=?',[$c['id']])->fetchColumn();if($parent&&in_array($parent,array_column($rows,'id'),true)&&!crHidden('comment',$parent))echo '<a class="sx-source" href="#comment-'.e($parent).'">'.e(nt('comment')).' ↩</a>';echo '<p data-user-content dir="auto">'.saRichText($c['body']).'</p>';$links=json_decode(socialQuery('SELECT document FROM social_comment_links WHERE comment=?',[$c['id']])->fetchColumn()?:'{}',true);crPhotoNotice($links['photos']??[]);foreach(crPhotos($links['photos']??[]) as $photo)echo '<img class="sc-comment-photo" src="/community/media/'.e($photo).'/" loading="lazy" alt="">';foreach($links['places']??[] as $pid)if($place=scCatalogue()[$pid]??null)scPlaceTile($place,true);foreach($links['routes']??[] as $rid)if($route=sxSource(['kind'=>'trip','target'=>$rid]))echo '<p><a href="'.e($route['url']).'">'.e($route['title']?:nt('trip')).'</a> <button type="button" data-social-copy="'.e($rid).'">'.e(rxT('use')).'</button></p>';if($u){echo '<button type="button" data-sx-reply="'.e($c['id']).'">'.e(nt('comment')).'</button>';$mine=$c['owner']===$u['id'];echo '<form method="post">'.csrf().networkContentLanguageField().'<input type="hidden" name="network_action" value="'.($mine?'delete_comment':'helpful').'"><input type="hidden" name="target" value="'.e($c['id']).'"><input type="hidden" name="on" value="1"><button>'.e(nt($mine?'delete':'helpful')).'</button></form>';}if($u&&!$mine)echo '<button type="button" data-cr-report="'.e($c['id']).'" data-cr-kind="comment">'.e(crT('report')).'</button>';echo '</article>';}
 if($u)echo '<form method="post" enctype="multipart/form-data" id="answer-editor">'.revReplyFields($kind,$id,$u).'<input type="hidden" name="comment_token" value="'.e(revCommentToken()).'">'.csrf().networkContentLanguageField().scCommentFields().'<input type="hidden" name="network_action" value="comment"><input type="hidden" name="kind" value="'.e($kind).'"><input type="hidden" name="target" value="'.e($id).'"><label>'.e(nt('comment_placeholder')).'<textarea name="body" required minlength="3" maxlength="2000" rows="3">'.e(($_POST['network_action']??'')==='comment'?($_POST['body']??''):'').'</textarea></label><button class="button">'.e(nt('comment')).'</button></form>';
 else echo '<a href="'.e(languageUrl('/community/account/',siteLanguage())).'">'.e(nt('login')).'</a>';echo '</section>';
}
function networkCard(array $r,bool $full=false): void {scCard($r,$full);}
function networkCatalogueCards(string $city='',array $exclude=[],string $country=''): void {
 $q=mb_strtolower(trim(is_string($_GET['q']??null)?$_GET['q']:''));$budget=in_array($_GET['budget']??'',['free','paid'],true)?$_GET['budget']:'';$minutes=max(0,(int)($_GET['minutes']??0));
 $pool=array_values(array_filter(tripCatalog(),fn($x)=>!str_starts_with($x['id'],'community-')&&!in_array(str_replace('community-','',$x['id']),$exclude,true)&&(!$city||$x['city']===$city)&&(!$country||(tripDestinations()[$x['city']]['country']??'')===$country)&&(!$budget||$x['cost']===$budget)&&(!$minutes||(isset($x['minutes'])&&$x['minutes']<=$minutes))&&(!$q||mb_strpos(mb_strtolower($x['title'].' '.$x['summary']),$q)!==false)));
 $buckets=[];foreach($pool as $x){$group=($city?$x['type']:$x['city']);$buckets[$x['cost']][$group]??=$x;}$items=[];$sets=array_map('array_values',$buckets);
 for($round=0;$round<6&&count($items)<6;$round++)foreach($sets as $set){if(count($items)>=6)break;$index=(int)floor($round*count($set)/max(1,(int)ceil(6/count($sets))));if(isset($set[$index])&&!isset($used[$set[$index]['id']])){$items[]=$set[$index];$used[$set[$index]['id']]=true;}}if(!$items)return;

 foreach($items as $x){echo '<article class="network-card network-library-card"><div class="network-author"><span class="network-author-link"><span class="network-avatar">T</span><span><strong>Tripovela</strong><small>'.e(nt('catalog_ideas')).(str_starts_with($x['url'],'/activities/')?' · Viator':'').'</small></span></span></div><div class="network-card-text"><span class="network-kicker">'.e(activityLabel(tripDestinations()[$x['city']]['labels']??[$x['city'],$x['city'],$x['city']])).' · '.e(nt($x['cost']==='free'?'free':($x['cost']==='paid'?'paid':'unknown'))).'</span><h2><a href="'.e($x['url']).'">'.e($x['title']).'</a></h2><p>'.e($x['summary']).'</p></div>';if($x['image'])echo '<a class="network-cover" href="'.e($x['url']).'"><img src="'.e($x['image']).'" alt="'.e($x['title']).'" width="1000" height="650" loading="lazy"></a>';echo '<div class="network-form">'.tripSaveButton($x).'<a class="network-action" href="'.e($x['url']).'">'.e(nt('read')).'</a></div><small class="network-credit">'.e($x['credit']).'</small></article>';}
}
function networkRouteDetails(array $p,array $catalog): void {
 $parent=$p['parent_route_id']??'';if($parent&&($r=socialPublicTrip($parent)))echo '<p>'.e(nt('based_on')).' <a href="'.e(networkUrl('trip',$parent)).'">@'.e($r['handle']).'</a></p>';
 foreach(journeyRouteWarnings($p) as $code)echo '<p class="notice">'.e(jt($code)).'</p>';

 // The route card now owns the itinerary, honest totals and map.

}
